-- Struktur tabel `attendance`
DROP TABLE IF EXISTS `attendance`;
CREATE TABLE `attendance` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `jam_masuk` varchar(20) DEFAULT NULL,
  `jam_masuk_iso` datetime DEFAULT NULL,
  `ekspresi_masuk` varchar(50) DEFAULT NULL,
  `screenshot_masuk` longtext DEFAULT NULL,
  `lokasi_masuk` varchar(255) DEFAULT NULL,
  `lat_masuk` decimal(10,7) DEFAULT NULL,
  `lng_masuk` decimal(10,7) DEFAULT NULL,
  `jam_pulang` varchar(20) DEFAULT NULL,
  `jam_pulang_iso` datetime DEFAULT NULL,
  `ekspresi_pulang` varchar(50) DEFAULT NULL,
  `screenshot_pulang` longtext DEFAULT NULL,
  `lokasi_pulang` varchar(255) DEFAULT NULL,
  `latitude_masuk` decimal(10,8) DEFAULT NULL,
  `longitude_masuk` decimal(11,8) DEFAULT NULL,
  `latitude_pulang` decimal(10,8) DEFAULT NULL,
  `longitude_pulang` decimal(11,8) DEFAULT NULL,
  `alasan_wfa` text DEFAULT NULL,
  `alasan_izin_sakit` text DEFAULT NULL,
  `bukti_izin_sakit` longtext DEFAULT NULL,
  `keterangan_izin_sakit` text DEFAULT NULL,
  `lat_pulang` decimal(10,7) DEFAULT NULL,
  `lng_pulang` decimal(10,7) DEFAULT NULL,
  `status` enum('ontime','terlambat') DEFAULT 'ontime',
  `ket` enum('wfo','izin','sakit','alpha','wfa') DEFAULT 'wfo',
  `wfa_reason` text DEFAULT NULL,
  `daily_report_id` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `fk_att_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=107 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

