-- Struktur tabel `attendance_notes`
DROP TABLE IF EXISTS `attendance_notes`;
CREATE TABLE `attendance_notes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `attendance_id` int(11) DEFAULT NULL,
  `tanggal` date NOT NULL,
  `jenis` enum('izin','sakit') NOT NULL,
  `keterangan` text NOT NULL,
  `bukti` longtext DEFAULT NULL,
  `bukti_file` longtext DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `date` date NOT NULL,
  `type` enum('izin','sakit') NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_date` (`user_id`,`date`),
  KEY `user_id` (`user_id`),
  KEY `attendance_id` (`attendance_id`),
  KEY `tanggal` (`tanggal`),
  CONSTRAINT `fk_att_notes_attendance` FOREIGN KEY (`attendance_id`) REFERENCES `attendance` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_att_notes_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

